const strip = text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');
const cfg = JSON.parse(strip);
function redact(v) {
  if (typeof v !== 'string') return v;
  if (/key|token|secret/i.test(v) || v.length > 20) return `${v.slice(0, 6)}...${v.slice(-4)} (${v.length})`;
  return v;
}
for (const [name, provider] of Object.entries(cfg.provider || {})) {
  if (/xai|grok|x-ai/i.test(name + JSON.stringify(provider))) {
    console.log(JSON.stringify({name, provider: JSON.parse(JSON.stringify(provider, (k,v)=> /key|token|secret/i.test(k) ? redact(v) : v))}, null, 2));
  }
}
console.log('model setting:', JSON.stringify(cfg.model || null));
