{"cmd":"node - <<'NODE'
const fs = require('fs');
const settingsPath = '/home/jeremy/.factory/settings.json';
const authPath = '/home/jeremy/.local/share/opencode/auth.json';
const modelsPath = '/home/jeremy/.cache/opencode/models.json';
const backupPath = `${settingsPath}.bak-${new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, '')}`;
const settings = JSON.parse(fs.readFileSync(settingsPath, 'utf8'));
const auth = JSON.parse(fs.readFileSync(authPath, 'utf8'));
const modelCache = JSON.parse(fs.readFileSync(modelsPath, 'utf8'));
const key = auth?.xai?.key;
if (!key || typeof key !== 'string' || !key.startsWith('xai-')) {
  throw new Error('No xAI API key found in opencode auth.json');
}
if (!Array.isArray(settings.customModels)) {
  throw new Error('settings.customModels is missing or not an array');
}
const xaiModels = modelCache?.xai?.models;
if (!xaiModels || typeof xaiModels !== 'object') {
  throw new Error('No xai model metadata found in opencode models cache');
}
const idByModel = {
  'grok-4.3': 'custom:Grok-4.3-[xAI-BYOK]-0',
  'grok-4.20-multi-agent-0309': 'custom:Grok-4.20-Multi-Agent-0309-[xAI-BYOK]-0',
  'grok-4.20-0309-non-reasoning': 'custom:Grok-4.20-0309-Non-Reasoning-[xAI-BYOK]-0',
  'grok-4.20-0309-reasoning': 'custom:Grok-4.20-0309-Reasoning-[xAI-BYOK]-0',
  'grok-build-0.1': 'custom:Grok-Build-0.1-[xAI-BYOK]-0',
};
const wanted = Object.values(xaiModels)
  .filter((model) => /grok/i.test(`${model.id} ${model.name}`))
  .filter((model) => Array.isArray(model.modalities?.output) && model.modalities.output.includes('text'))
  .filter((model) => Number(model.limit?.output || 0) > 0)
  .map((model) => ({
    model: model.id,
    name: model.name,
    id: idByModel[model.id] || `custom:${model.id.replace(/[^A-Za-z0-9.]+/g, '-')}-[xAI-BYOK]-0`,
    maxOutputTokens: Number(model.limit.output),
  }));
if (wanted.length === 0) {
  throw new Error('No chat-capable Grok models found in opencode xai cache');
}
fs.copyFileSync(settingsPath, backupPath);
let maxIndex = settings.customModels.reduce((max, model) => Math.max(max, Number(model.index) || 0), -1);
const results = [];
for (const item of wanted) {
  const existing = settings.customModels.find((model) => model.id === item.id || (model.baseUrl === 'https://api.x.ai/v1' && model.model === item.model));
  const entry = {
    model: item.model,
    id: item.id,
    index: existing?.index ?? ++maxIndex,
    baseUrl: 'https://api.x.ai/v1',
    apiKey: key,
    displayName: `${item.name} [xAI BYOK]`,
    maxOutputTokens: item.maxOutputTokens,
    noImageSupport: true,
    provider: 'generic-chat-completion-api',
  };
  if (existing) {
    Object.assign(existing, entry);
    results.push({ action: 'updated', id: entry.id, index: entry.index, model: entry.model, displayName: entry.displayName, maxOutputTokens: entry.maxOutputTokens });
  } else {
    settings.customModels.push(entry);
    results.push({ action: 'added', id: entry.id, index: entry.index, model: entry.model, displayName: entry.displayName, maxOutputTokens: entry.maxOutputTokens });
  }
}
